"""Versioned dataset paths: a dataset generated by one DuckDB version is never regenerated in place."""

from __future__ import annotations

from pathlib import Path

import pytest

from krishiv_bench import paths
from krishiv_bench.paths import dataset_dir, manifest_stem, split_dataset


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.setenv("KRISHIV_DATA", str(tmp_path))
    return tmp_path


def test_unversioned_name_keeps_legacy_layout(root: Path):
    assert split_dataset("tpch-dbgen") == ("tpch-dbgen", None)
    assert dataset_dir("tpch-dbgen", 1) == root / "tpch-dbgen" / "sf1"
    assert manifest_stem("tpch-dbgen", 1) == "tpch-dbgen-sf1"


def test_versioned_name_gets_its_own_directory_and_manifest(root: Path):
    assert split_dataset("tpch-dbgen@2.0.0") == ("tpch-dbgen", "2.0.0")
    assert dataset_dir("tpch-dbgen@2.0.0", 1) == root / "tpch-dbgen" / "sf1-dbgen-2.0.0"
    assert dataset_dir("tpch-dbgen@2.0.0", 10) == root / "tpch-dbgen" / "sf10-dbgen-2.0.0"
    assert manifest_stem("tpch-dbgen@2.0.0", 1) == "tpch-dbgen-sf1-dbgen-2.0.0"
    assert dataset_dir("tpch-dbgen@2.0.0", 1) != dataset_dir("tpch-dbgen", 1)


def test_fractional_sf_is_formatted_as_before(root: Path):
    assert paths.dataset_leaf(0.5) == "sf0.5"
    assert paths.dataset_leaf(0.5, "2.0.0") == "sf0.5-dbgen-2.0.0"
